/**
 * ハンドブックの実装由来入力(`lib/gen-kit/book-inputs.ts`)のテスト。
 *
 * 対象の要求: 「SSR プレビューの断片ファイルは `{画面名}.html` で、先頭行の
 * AUTO-GENERATED 注意書きを落としたものが中身である」。
 */

import { describe, expect, it } from 'vitest';

import {
  parsePreviewFile,
  previewScreenOf,
  previewStateOf,
  stateKeyOf,
} from '../../../../../lib/gen-kit/book-inputs.js';

describe('previewScreenOf', () => {
  it('ファイル名から画面名を読む', () => {
    expect(previewScreenOf('workshop_detail.html')).toBe('workshop_detail');
  });

  it('規則に合わない名前は null(黙って画面へ割り付けない)', () => {
    expect(previewScreenOf('workshop-detail.html')).toBeNull();
    expect(previewScreenOf('WorkshopDetail.html')).toBeNull();
    expect(previewScreenOf('manifest.json')).toBeNull();
  });

  it('状態別断片(`.` が 2 つ)は拾わない ―― previewStateOf の側の仕事である', () => {
    expect(previewScreenOf('workshop_list.empty.html')).toBeNull();
  });
});

describe('previewStateOf', () => {
  it('ファイル名から画面名と状態を読む', () => {
    expect(previewStateOf('workshop_list.empty.html')).toEqual({ screen: 'workshop_list', state: 'empty' });
    expect(previewStateOf('public_page.not_found.html')).toEqual({
      screen: 'public_page',
      state: 'not_found',
    });
  });

  it('既定断片(`.` が 1 つ)は拾わない ―― previewScreenOf の側の仕事である', () => {
    expect(previewStateOf('workshop_list.html')).toBeNull();
  });

  it('規則に合わない名前は null', () => {
    expect(previewStateOf('WorkshopList.empty.html')).toBeNull();
    expect(previewStateOf('manifest.json')).toBeNull();
  });
});

describe('stateKeyOf', () => {
  it('previewStateOf が読んだ画面名と状態から同じキーを組み立てる', () => {
    const key = previewStateOf('workshop_list.empty.html');
    expect(key === null ? null : stateKeyOf(key.screen, key.state)).toBe('workshop_list.empty');
  });
});

describe('parsePreviewFile', () => {
  it('先頭の AUTO-GENERATED 行を落として中身だけを返す', () => {
    const file = '<!-- AUTO-GENERATED by `npm run book:previews` -->\n<main class="pageWide"></main>\n';

    expect(parsePreviewFile(file)).toBe('<main class="pageWide"></main>');
  });

  it('注意書きが無いファイルは全体が中身', () => {
    expect(parsePreviewFile('<main></main>\n')).toBe('<main></main>');
  });
});
